package com.example.appointment.staff;
import com.example.appointment.common.BaseEntity; import com.example.appointment.offering.ServiceOffering; import com.example.appointment.user.User; import java.util.*; import javax.persistence.*;
@Entity @Table(name="staff_profile") public class StaffProfile extends BaseEntity { @OneToOne(optional=false) private User user; private String specialisation; @Column(nullable=false) private boolean active=true; @ManyToMany @JoinTable(name="staff_service",joinColumns=@JoinColumn(name="staff_id"),inverseJoinColumns=@JoinColumn(name="service_id")) private Set<ServiceOffering> services=new HashSet<>(); protected StaffProfile(){} public StaffProfile(User u,String s){user=u;specialisation=s;} public User getUser(){return user;} public String getSpecialisation(){return specialisation;} public boolean isActive(){return active;} public Set<ServiceOffering> getServices(){return services;} public void update(String s,boolean a){specialisation=s;active=a;} }
